:root {
  --bg: #1e1b2e;
  --card: #2a2640;
  --text: #f0eef6;
  --muted: #b4aed0;
  --accent: #7c5cff;
  --accent-hover: #9a80ff;
  --accent-press: #5f3fe0;
  --error: #ff6b6b;
  --focus: #ffd166;
  --radius: 14px;
}

* { box-sizing: border-box; }

[hidden] { display: none !important; }

body {
  margin: 0;
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background: radial-gradient(circle at 20% 10%, #322b52 0%, var(--bg) 60%);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 17px;
  line-height: 1.5;
}

.card {
  width: 100%;
  max-width: 480px;
  background: var(--card);
  border: 1px solid #3d3760;
  border-radius: var(--radius);
  padding: 32px 28px;
  box-shadow: 0 18px 40px rgba(0, 0, 0, 0.45);
}

h1 {
  margin: 0 0 6px;
  font-size: 1.6rem;
  letter-spacing: -0.02em;
}

.subtitle {
  margin: 0 0 24px;
  color: var(--muted);
  font-size: 0.95rem;
}

form { display: grid; gap: 18px; }

.field { display: grid; gap: 6px; }

label {
  font-weight: 600;
  font-size: 0.95rem;
}

.input-wrap {
  display: flex;
  align-items: center;
  background: #1b1830;
  border: 1px solid #453e6b;
  border-radius: 10px;
  padding: 0 12px;
  transition: border-color 0.15s, box-shadow 0.15s;
}

.input-wrap:focus-within {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(124, 92, 255, 0.35);
}

.currency {
  color: var(--muted);
  font-weight: 600;
  padding-right: 6px;
}

input {
  flex: 1;
  min-width: 0;
  background: transparent;
  border: 0;
  outline: none;
  color: var(--text);
  font: inherit;
  font-size: 1.05rem;
  padding: 12px 0;
}

input::placeholder { color: #6f6894; }

.hint {
  color: var(--muted);
  font-size: 0.85rem;
}

button {
  margin-top: 4px;
  padding: 14px 18px;
  border: 0;
  border-radius: 10px;
  background: var(--accent);
  color: #fff;
  font: inherit;
  font-weight: 700;
  font-size: 1.05rem;
  cursor: pointer;
  transition: background 0.15s, transform 0.05s;
}

button:hover { background: var(--accent-hover); }

button:active { background: var(--accent-press); transform: translateY(1px); }

button:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

input:focus-visible { outline: none; }

.error {
  margin-top: 18px;
  padding: 12px 14px;
  border-radius: 10px;
  background: rgba(255, 107, 107, 0.12);
  border: 1px solid rgba(255, 107, 107, 0.5);
  color: var(--error);
  font-weight: 600;
}

.results {
  margin-top: 26px;
  padding-top: 22px;
  border-top: 1px solid #3d3760;
}

h2 {
  margin: 0 0 8px;
  font-size: 1.15rem;
}

.change-total {
  margin: 0 0 14px;
  font-size: 1.8rem;
  font-weight: 800;
  color: var(--accent-hover);
  letter-spacing: -0.02em;
}

.change-empty {
  margin: 0;
  color: var(--muted);
  font-style: italic;
}

.breakdown {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
}

.breakdown li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 14px;
  background: #1b1830;
  border-radius: 9px;
  border: 1px solid #38315a;
}

.breakdown .denom { font-weight: 700; }

.breakdown .count {
  color: var(--muted);
  font-variant-numeric: tabular-nums;
}

@media (max-width: 400px) {
  .card { padding: 24px 18px; }
  h1 { font-size: 1.35rem; }
  .change-total { font-size: 1.5rem; }
}

(function () {
  'use strict';

  var DENOMINATIONS = [2000, 1000, 500, 200, 100, 50, 20, 10, 5];

  var form = document.getElementById('change-form');
  var priceInput = document.getElementById('price');
  var paidInput = document.getElementById('paid');
  var errorBox = document.getElementById('error');
  var results = document.getElementById('results');
  var changeTotal = document.getElementById('change-total');
  var changeEmpty = document.getElementById('change-empty');
  var breakdown = document.getElementById('breakdown');

  function parseMoney(value) {
    var trimmed = String(value).trim();
    if (trimmed === '') return null;
    if (!/^\d+(\.\d{1,2})?$/.test(trimmed)) return null;
    var parts = trimmed.split('.');
    var whole = parseInt(parts[0], 10);
    var cents = parts[1] ? parseInt((parts[1] + '00').slice(0, 2), 10) : 0;
    return whole * 100 + cents;
  }

  function formatMoney(cents) {
    var whole = Math.floor(cents / 100);
    var rem = cents % 100;
    return '$' + whole + '.' + (rem < 10 ? '0' : '') + rem;
  }

  function showError(message) {
    errorBox.textContent = message;
    errorBox.hidden = false;
    results.hidden = true;
  }

  function clearError() {
    errorBox.textContent = '';
    errorBox.hidden = true;
  }

  function render(cents) {
    clearError();
    results.hidden = false;
    changeTotal.textContent = formatMoney(cents);
    breakdown.innerHTML = '';

    if (cents === 0) {
      changeEmpty.hidden = false;
      return;
    }
    changeEmpty.hidden = true;

    var remaining = cents;
    DENOMINATIONS.forEach(function (denom) {
      var count = Math.floor(remaining / denom);
      if (count > 0) {
        remaining -= count * denom;
        var li = document.createElement('li');
        var d = document.createElement('span');
        d.className = 'denom';
        d.textContent = formatMoney(denom);
        var c = document.createElement('span');
        c.className = 'count';
        c.textContent = '\u00d7 ' + count;
        li.appendChild(d);
        li.appendChild(c);
        breakdown.appendChild(li);
      }
    });
  }

  function handleSubmit(event) {
    event.preventDefault();
    var price = parseMoney(priceInput.value);
    var paid = parseMoney(paidInput.value);

    if (price === null) {
      showError('Please enter a valid price (e.g. 4.75).');
      priceInput.focus();
      return;
    }
    if (paid === null) {
      showError('Please enter a valid amount paid (e.g. 10.00).');
      paidInput.focus();
      return;
    }
    if (paid < price) {
      showError('Amount paid is less than the price. Short by ' + formatMoney(price - paid) + '.');
      paidInput.focus();
      return;
    }

    render(paid - price);
  }

  form.addEventListener('submit', handleSubmit);
})();
